func TestLocalPolicySourceCopyPolicy_CopiesManifestAndBlob(t *testing.T) {
	ctx := context.Background()
	layoutPath, manifestDigest, sourceBlob := createLocalPolicyLayout(t, ctx)
	source := cache.NewLocalPolicySource(layoutPath)
	destination, err := ocistore.New(t.TempDir())
	require.NoError(t, err)

	descriptor, err := source.CopyPolicy(ctx, "policies/test", manifestDigest, destination)

	require.NoError(t, err)
	assert.Equal(t, manifestDigest, descriptor.Digest.String())
	manifestExists, err := destination.Exists(ctx, descriptor)
	require.NoError(t, err)
	assert.True(t, manifestExists)
	blobExists, err := destination.Exists(ctx, sourceBlob)
	require.NoError(t, err)
	assert.True(t, blobExists)
}

