func TestLocalPolicySourceCopyPolicy_TamperedManifestLeavesDestinationUnchanged(t *testing.T) {
	ctx := context.Background()
	layoutPath, manifestDigest, sourceBlob := createLocalPolicyLayout(t, ctx)
	manifest := digest.Digest(manifestDigest)
	manifestPath := filepath.Join(layoutPath, ocispec.ImageBlobsDir, manifest.Algorithm().String(), manifest.Encoded())
	manifestContent, err := os.ReadFile(manifestPath)
	require.NoError(t, err)
	require.NotEmpty(t, manifestContent)
	manifestContent[0] ^= 1
	require.NoError(t, os.Chmod(manifestPath, 0o600))
	// #nosec G703 -- manifestPath is derived from the trusted test fixture digest.
	require.NoError(t, os.WriteFile(manifestPath, manifestContent, 0o600))

	source := cache.NewLocalPolicySource(layoutPath)
	destination, err := ocistore.New(t.TempDir())
	require.NoError(t, err)

	_, err = source.CopyPolicy(ctx, "policies/test", manifestDigest, destination)

	require.Error(t, err)
	manifestExists, err := destination.Exists(ctx, ocispec.Descriptor{Digest: manifest})
	require.NoError(t, err)
	assert.False(t, manifestExists)
	blobExists, err := destination.Exists(ctx, sourceBlob)
	require.NoError(t, err)
	assert.False(t, blobExists)
}

