func TestLocalComplypackSourceCopyComplypack_ValidArtifactCopiesFullDAG(t *testing.T) {
	ctx := context.Background()
	layoutPath, manifestDigest := createLocalComplypackLayout(t, ctx)
	source := cache.NewLocalComplypackSource(layoutPath)
	destination, err := ocistore.New(t.TempDir())
	require.NoError(t, err)

	descriptor, err := source.CopyComplypack(ctx, "complypacks/test", manifestDigest, destination)

	require.NoError(t, err)
	assert.Equal(t, manifestDigest, descriptor.Digest.String())
	assert.Equal(t, complypack.MediaTypeArtifact, descriptor.ArtifactType)
	result, err := complypack.Unpack(ctx, destination, descriptor)
	require.NoError(t, err)
	defer result.Content.Close()
	assert.Equal(t, "io.complytime.test", result.Config.EvaluatorID)
}

func TestLocalComplypackSourceCopyComplypack_InvalidMediaTypeLeavesDestinationUnchanged(t *testing.T) {
	ctx := context.Background()
	layoutPath, manifestDigest, sourceBlob := createLocalPolicyLayout(t, ctx)
	source := cache.NewLocalComplypackSource(layoutPath)
	destination, err := ocistore.New(t.TempDir())
	require.NoError(t, err)

	_, err = source.CopyComplypack(ctx, "complypacks/test", manifestDigest, destination)

	require.Error(t, err)
	assert.Contains(t, err.Error(), "artifact type mismatch")
	manifestExists, err := destination.Exists(ctx, ocispec.Descriptor{Digest: digest.Digest(manifestDigest)})
	require.NoError(t, err)
	assert.False(t, manifestExists)
	blobExists, err := destination.Exists(ctx, sourceBlob)
	require.NoError(t, err)
	assert.False(t, blobExists)
}

