func TestLocalComplypackSource_TamperedManifestLeavesCacheAndStateUnchanged(t *testing.T) {
	ctx := context.Background()
	layoutPath, manifestDigest := createLocalComplypackLayout(t, ctx)
	manifest := digest.Digest(manifestDigest)
	manifestPath := filepath.Join(layoutPath, ocispec.ImageBlobsDir, manifest.Algorithm().String(), manifest.Encoded())
	manifestContent, err := os.ReadFile(manifestPath)
	require.NoError(t, err)
	manifestContent[0] ^= 1
	require.NoError(t, os.Chmod(manifestPath, 0o600))
	// #nosec G703 -- manifestPath is derived from the trusted test fixture digest.
	require.NoError(t, os.WriteFile(manifestPath, manifestContent, 0o600))

	cacheDir := t.TempDir()
	state, err := cache.LoadState(cacheDir)
	require.NoError(t, err)
	complypackCache := cache.NewComplypackCache(cacheDir, state)
	syncer := cache.NewComplypackSync(
		complypackCache,
		state,
		cache.NewLocalComplypackSource(layoutPath),
		cacheDir,
		"",
	)

	_, err = syncer.SyncComplypack(ctx, "complypacks/test", manifestDigest)

	require.Error(t, err)
	_, stateExists := state.GetComplypackState("complypacks/test")
	assert.False(t, stateExists)
	contentPath, _, err := complypackCache.LookupByEvaluatorID("io.complytime.test")
	require.NoError(t, err)
	assert.Empty(t, contentPath)
}

func createLocalPolicyLayout(t *testing.T, ctx context.Context) (string, string, ocispec.Descriptor) {
	t.Helper()
	layoutPath := t.TempDir()
	store, err := ocistore.New(layoutPath)
	require.NoError(t, err)
	blobData := []byte("policy content")
	blobDescriptor := ocispec.Descriptor{
		MediaType: "application/vnd.complytime.policy.layer.v1",
		Digest:    digest.FromBytes(blobData),
		Size:      int64(len(blobData)),
	}
	require.NoError(t, store.Push(ctx, blobDescriptor, bytes.NewReader(blobData)))

	descriptor, err := oras.PackManifest(
		ctx,
		store,
		oras.PackManifestVersion1_1,
		"application/vnd.complytime.policy.v1",
		oras.PackManifestOptions{Layers: []ocispec.Descriptor{blobDescriptor}},
	)
	require.NoError(t, err)
	return layoutPath, descriptor.Digest.String(), blobDescriptor
}

func createLocalComplypackLayout(t *testing.T, ctx context.Context) (string, string) {
	t.Helper()
	layoutPath := t.TempDir()
	store, err := ocistore.New(layoutPath)
	require.NoError(t, err)
	descriptor, err := complypack.Pack(
		ctx,
		store,
		complypack.Config{ID: "io.complytime.test-pack", EvaluatorID: "io.complytime.test", Version: "1.0.0"},
		bytes.NewReader([]byte("complypack content")),
	)
	require.NoError(t, err)
	return layoutPath, descriptor.Digest.String()
}

func writeEmptyOCIIndex(t *testing.T, layoutPath string) {
	t.Helper()
	require.NoError(t, os.WriteFile(filepath.Join(layoutPath, ocispec.ImageIndexFile), []byte(`{"schemaVersion":2}`), 0o600))
}
